<?php
require_once __DIR__.'/../config/security.php'; require_permission('backup.manage');
$dir=__DIR__.'/../backups'; if(!is_dir($dir))mkdir($dir,0700,true);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $file='campus_network_'.date('Ymd_His').'.sql';$path=$dir.'/'.$file;$host='127.0.0.1';$user='root';$pass='';$db='campus_network';$cmd='mysqldump --host='.escapeshellarg($host).' --user='.escapeshellarg($user).' '.($pass!==''?'--password='.escapeshellarg($pass).' ':'').escapeshellarg($db).' > '.escapeshellarg($path);exec($cmd,$o,$code);if($code!==0||!file_exists($path))json_response(['ok'=>false,'message'=>'mysqldump failed. Ensure mysqldump is installed and executable.'],500);$size=filesize($path);$pdo->prepare('INSERT INTO backups(filename,file_path,created_by,size_bytes) VALUES(?,?,?,?)')->execute([$file,$path,$_SESSION['user_id'],$size]);audit('Created database backup',$file);json_response(['ok'=>true,'filename'=>$file]);}
if($_SERVER['REQUEST_METHOD']==='GET'){ $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM backups WHERE id=?');$st->execute([$id]);$b=$st->fetch();if(!$b||!is_file($b['file_path']))json_response(['ok'=>false,'message'=>'Backup not found'],404);header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="'.basename($b['filename']).'"');readfile($b['file_path']);exit; }
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_FILES['sql_file']) && ($_POST['action']??'')==='restore'){if(empty($_FILES['sql_file']))json_response(['ok'=>false,'message'=>'SQL file is required.'],422);$tmp=$_FILES['sql_file']['tmp_name'];if(strtolower(pathinfo($_FILES['sql_file']['name'],PATHINFO_EXTENSION))!=='sql')json_response(['ok'=>false,'message'=>'Only .sql files are accepted.'],422);$host='127.0.0.1';$user='root';$pass='';$db='campus_network';$cmd='mysql --host='.escapeshellarg($host).' --user='.escapeshellarg($user).' '.($pass!==''?'--password='.escapeshellarg($pass).' ':'').escapeshellarg($db).' < '.escapeshellarg($tmp);exec($cmd,$o,$code);if($code!==0)json_response(['ok'=>false,'message'=>'Database restore failed.'],500);audit('Restored database',$_FILES['sql_file']['name']);security_event('database_restore','Critical','Database restored from SQL file');json_response(['ok'=>true,'message'=>'Database restore completed.']);}
json_response(['ok'=>false,'message'=>'Unsupported request'],405);
